// Multi-point measurement sheets; shared between field, PM and design workspaces.
const Measurements={
 rows(s){return s.rows||[{point:s.point||'',metric:'历史实测记录',design:'',value:s.value,unit:s.unit||'mm',remark:'原始单测点记录，未补造设计值'}];},
 state(s){return ({draft:'草稿',pending:'待资料核验',usable:'资料可用',returned:'待补测 / 修正'})[s.status]||s.status;},
 difference(r){return r.design!==''&&r.design!=null&&r.value!==''&&r.value!=null&&Number.isFinite(+r.design)&&Number.isFinite(+r.value)?Math.round((+r.value-(+r.design))*1e6)/1e6:'';},
 table(s){return `<div class="tablewrap"><table class="measurement-table"><thead><tr>${['测点 / 构件','测量项目','设计值','实测值','单位','偏差','备注'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${this.rows(s).map(r=>`<tr>${[r.point,r.metric,r.design,r.value,r.unit,this.difference(r),r.remark].map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;},
 page(){return head('MEASUREMENT','基层测量台账','一个工作面、一张多测点表；整表核验，统一导出与打印。',S.role==='worker'?b('＋ 新建测量表','survey'):'')+`<div class="actions measurement-tools">${b('导出全部 Excel','measurementExport')}${b('打印全部测量表','measurementPrint')}</div><p class="quiet">导出当前台账全部测点，包含状态与空缺项；空值不当作零。资料可用不等于实体合格。</p>`+S.surveys.map(s=>`<section class="fieldcard card"><div class="cardbody"><div class="row between"><h2>${esc(s.title||s.location)}</h2>${tag(this.state(s),s.status==='usable'?'teal':'amber')}</div><p>${esc(s.location)} · ${esc(s.id)} · 第 ${s.revision||1} 版 · ${this.rows(s).length} 个测点</p><p class="quiet">测量日期：${esc(s.date||'历史记录未填写')} · 测量人：${esc(s.operator||'历史记录未填写')} · 仪器：${esc(s.instrument||'未填写')}</p><p>基准 / 图纸依据：${esc(s.reference||'待填写')}</p>${s.opinion?`<div class="note">核验意见：${esc(s.opinion)}</div>`:''}${this.table(s)}<div class="actions" style="margin-top:16px">${S.role==='worker'&&['draft','returned'].includes(s.status)?b('继续填写测量表','survey',s.id,'primary'):''}${S.role==='pm'&&s.status==='pending'?b('核验整张表','verifySurvey',s.id,'primary'):''}${b('导出本表 Excel','measurementExport',s.id)}${b('打印本表','measurementPrint',s.id)}${S.role==='worker'?b('依据本表报问题','measurementIssue',s.id):''}</div>${s.history?.length?`<details class="fieldfold"><summary>查看历史提交版本（${s.history.length}）</summary>${s.history.map(h=>`<div class="fieldrecord"><strong>第 ${h.revision} 版 · ${esc(this.state(h))}</strong><p>${esc(h.opinion||'')}</p>${this.table(h)}</div>`).join('')}</details>`:''}</div></section>`).join('');},
 row(r={},n=1){return `<fieldset class="measurement-row"><legend>测点 ${n}</legend><div class="two"><label>测点 / 构件编号<input data-col="point" aria-label="测点 ${n} 编号" value="${esc(r.point)}"></label><label>测量项目<input data-col="metric" aria-label="测点 ${n} 项目" value="${esc(r.metric)}" placeholder="如标高、净距"></label></div><div class="two"><label>设计值（可空）<input type="number" step="any" data-col="design" aria-label="测点 ${n} 设计值" value="${esc(r.design)}"></label><label>原始实测值<input type="number" step="any" data-col="value" aria-label="测点 ${n} 实测值" value="${esc(r.value)}"></label></div><div class="two"><label>单位<select data-col="unit" aria-label="测点 ${n} 单位">${['mm','m','°','MPa'].map(u=>`<option ${u===(r.unit||'mm')?'selected':''}>${u}</option>`).join('')}</select></label><label>备注<input data-col="remark" aria-label="测点 ${n} 备注" value="${esc(r.remark)}"></label></div><button type="button" data-action="measurementRemove">移除此测点</button></fieldset>`;},
 form(id){const s=S.surveys.find(x=>x.id===id)||{},rows=s.id?this.rows(s):[{}];return '<div class="note">同一工作面的多个测点填写在一张表中，无需逐点上传附件。可暂存后继续填写，完成后整表提交。</div>'+input('title','测量表名称',s.title||'基层实测实量记录表')+input('location','工作面 / 位置',s.location||S.tasks[0]?.location||'')+`<div class="two">${input('date','测量日期',s.date||new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date()),'date')}${input('operator','测量人',s.operator||M.people.worker)}</div>`+input('instrument','仪器 / 编号',s.instrument||'')+area('reference','测量基准与图纸依据',s.reference||'')+`<div id="measurementRows">${rows.map((r,n)=>this.row(r,n+1)).join('')}</div><button type="button" data-action="measurementAdd">＋ 添加测点</button><p class="quiet">设计值留空时不计算偏差；本表不自动作出合格判定。</p>`;},
 collect(){return [...$('measurementRows').querySelectorAll('.measurement-row')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-col]')].map(el=>[el.dataset.col,el.value.trim()])));},
 payload(){const p=values();p.rows=this.collect();return p;},
 dataset(list){return [['表号','版本','表名','工作面','测量日期','测量人','仪器','测量基准与图纸依据','资料状态','测点 / 构件','测量项目','设计值','实测值','单位','偏差（实测-设计）','备注','核验意见'],...list.flatMap(s=>this.rows(s).map(r=>[s.id,s.revision||1,s.title||'基层测量记录',s.location,s.date||'',s.operator||'',s.instrument||'',s.reference||'',this.state(s),r.point,r.metric,r.design===''||r.design==null?'':Number(r.design),r.value===''||r.value==null?'':Number(r.value),r.unit,this.difference(r),r.remark||'',s.opinion||'']))];},
 export(id){const list=id?S.surveys.filter(x=>x.id===id):S.surveys;if(!list.length){toast('暂无测量数据');return;}const blob=MeasurementXlsx(this.dataset(list));const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(id||'全部基层测量数据')+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},
 print(id){const list=id?S.surveys.filter(x=>x.id===id):S.surveys;if(!list.length){toast('暂无测量数据');return;}let paper=$('measurementPrint');if(!paper){paper=document.createElement('div');paper.id='measurementPrint';document.body.appendChild(paper);}paper.innerHTML='<div class="print-controls"><button data-action="measurementPrintClose">返回测量台账</button><button data-action="measurementPrintNow">打印 / 另存 PDF</button><p>如内置浏览器未弹出打印窗口，可用系统浏览器打开原型，或用导出的 Excel 打印。</p></div>'+list.map(s=>`<section class="print-sheet"><h1>${esc(s.title||'基层实测实量记录表')}</h1><p>项目：滨江商务中心 T2（演示）　表号：${esc(s.id)}　第 ${s.revision||1} 版　状态：${esc(this.state(s))}</p><p>工作面：${esc(s.location)}　日期：${esc(s.date||'未填写')}　测量人：${esc(s.operator||'未填写')}</p><p>仪器：${esc(s.instrument||'未填写')}　基准与依据：${esc(s.reference)}</p>${this.table(s)}<p>核验意见：${esc(s.opinion||'待核验')}　测量签认：________　复核签认：________</p><p>偏差仅按同单位实测值减设计值计算，不代表合格判定。演示数据不作为正式工程记录。</p></section>`).join('');document.body.classList.add('measurement-preview');window.scrollTo(0,0);},
 handle(action,id,x){if(action==='measurementPrintClose'){document.body.classList.remove('measurement-preview','printing-measurement');return true;}if(action==='measurementPrintNow'){document.body.classList.add('printing-measurement');window.print();return true;}if(action==='measurementAdd'){$('measurementRows').insertAdjacentHTML('beforeend',this.row({},$('measurementRows').children.length+1));return true;}if(action==='measurementRemove'){x.closest('.measurement-row').remove();return true;}if(action==='measurementExport'){this.export(id);return true;}if(action==='measurementPrint'){this.print(id);return true;}if(action==='measurementIssue'){const s=S.surveys.find(x=>x.id===id);showModal('report');$('f-location').value=s.location;$('form').insertAdjacentHTML('beforeend',`<input type="hidden" name="surveyRef" value="${esc(s.id)}">`);const task=$('f-task');if(task)task.value='';$('f-text').value=`关联基层测量表：${s.id}（第 ${s.revision||1} 版）。异常测点及现象：`;return true;}if(action==='saveDraft'&&modal?.type==='survey'){try{S=M.apply(S,'saveSurvey',this.payload());persist();closeModal();nav('surveys');toast('测量表已暂存，可在台账继续填写');}catch(e){$('formError').textContent=e.message;}return true;}return false;}
};
if(typeof window!=='undefined')window.addEventListener('afterprint',()=>document.body.classList.remove('printing-measurement'));
if(typeof module!=='undefined')module.exports=Measurements;
